//! Auto-generated document section serializer for DOCX output.
//!
//! [`AutoSectionSerializer`] converts a [`slideforge_layout::sections::GeneratedSection`]
//! with [`slideforge_layout::sections::SectionSource::AutoGenerated`] into
//! `<w:body>` XML paragraphs (for executive summary) or a `<w:tbl>` table (for
//! risk register).
//!
//! ## Dispatch model (BC-4.02.002 invariant 1 / DI-008)
//!
//! Section rendering is dispatched on the section kind string — no hardcoded
//! `if section_name == "executive_summary"` chains. The dispatcher calls the
//! appropriate serialization helper based on [`slideforge_layout::sections::SectionKind`]:
//!
//! | `SectionKind` | Rendered as |
//! |--------------|------------|
//! | `ExecutiveSummary` | `Heading1` + bullet `Normal` paragraphs |
//! | `RiskRegister`     | `Heading1` + `<w:tbl>` with header + data rows |
//!
//! ## Empty-section guard (BC-4.02.002 invariant 2)
//!
//! If [`GeneratedSection::items`] is empty, the serializer returns an empty
//! `Vec` — no XML is emitted for the section. Callers must not emit an empty
//! `Heading1` without content.
//!
//! ## ooxmlsdk usage
//!
//! All `<w:tbl>`, `<w:tr>`, `<w:tc>` elements are constructed via ooxmlsdk
//! typed builders (BC-4.02.002 Architecture rule 4). No string XML
//! concatenation for dynamic content.

use ooxmlsdk::schemas::schemas_openxmlformats_org_wordprocessingml_2006_main::{
    Body, BodyChoice,
};
use slideforge_layout::sections::GeneratedSection;

use crate::error::ExportError;

/// Serializes auto-generated [`GeneratedSection`] entries into `<w:body>` XML.
///
/// Dispatches on [`slideforge_layout::sections::SectionKind`] to select the
/// appropriate rendering helper. Returns an empty `Vec` for sections with no
/// items (BC-4.02.002 invariant 2).
pub struct AutoSectionSerializer;

impl AutoSectionSerializer {
    /// Create a new serializer.
    #[must_use]
    pub fn new() -> Self {
        Self
    }

    /// Serialize one auto-generated section into a list of [`BodyChoice`] elements.
    ///
    /// Returns an empty `Vec` if `section.items` is empty (invariant 2).
    ///
    /// # Errors
    ///
    /// Returns [`ExportError::OoxmlError`] if OOXML construction fails.
    pub fn serialize_section(
        &self,
        section: &GeneratedSection,
    ) -> Result<Vec<BodyChoice>, ExportError> {
        todo!(
            "AutoSectionSerializer::serialize_section — not yet implemented (STORY-042 Step 4). \
             Section kind: {:?}, items: {}",
            section.kind,
            section.items.len()
        )
    }
}

impl Default for AutoSectionSerializer {
    fn default() -> Self {
        Self::new()
    }
}

